/*=============================================================================* 
 * 오늘날짜 생성
 * 
 * param : 
 *
 * return : tdy
 *============================================================================*/


/**
 * @method
 * @name todate
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.todate = function() {
    var now = new Date();
    var jyear = now.getYear();
    var month = now.getMonth() + 1;
    var jmonth = month + "";
    if (jmonth.length < 2) {
        jmonth = "0" + jmonth;
    }
    var dat = now.getDate();
    var jdate = dat + "";
    if (jdate.length < 2) {
        jdate = "0" + jdate;
    }
    var tdy = jyear + jmonth + jdate;
    return tdy;
};
/**
 * @method
 * @name todate_slash
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.todate_slash = function() {
    var now = new Date();
    var jyear = now.getYear();
    var month = now.getMonth() + 1;
    var jmonth = month + "";
    if (jmonth.length < 2) {
        jmonth = "0" + jmonth;
    }
    var dat = now.getDate();
    var jdate = dat + "";
    if (jdate.length < 2) {
        jdate = "0" + jdate;
    }
    var tdy = jyear + "/" + jmonth + "/" + jdate;
    return tdy;
};



// 공통메세지 정의 : 계속추가해야함. 
// MSG-A***로 시작하는건 ^로 대체되는 문자가 있는 경우
messageKeys = [{
    key: "MSG-A001",
    content: "[^] 처리 성공하였습니다."
}, {
    key: "MSG-0001",
    content: "성공적으로 처리되었습니다."
}, {
    key: "MSG-A002",
    content: "[^] 처리 실패하였습니다."
}, {
    key: "MSG-0002",
    content: "작업처리 중 오류가 발생하였습니다."
}, {
    key: "MSG-0003",
    content: "조회결과가 없습니다."
}, {
    key: "MSG-0004",
    content: "정보를  변경하시겠습니까?"
}, {
    key: "MSG-A005",
    content: "[^] 을(를) 입력하셔야 합니다."
}, {
    key: "MSG-A006",
    content: "[^] 처리를 하시겠습니까?"
}, {
    key: "MSG-A007",
    content: "[^] 기 등록된 그룹이 있어 그룹지정 하지 않음.\r\n 권한확인(40010화면)"
}, {
    key: "MSG-A008",
    content: "[^] 그룹지정 실패(사용자 정보 저장은 성공).\r\n로그를 확인하세요."
}];



/**	
 * 
 * 1. 설 명
 *    파라미터로 들어온 Key값을 이용하여 해당 Message를 출력한다.
 *
 * 2. 특이사항
 *    key와 일치하는 값이 없을 경우 해당 key값을 리턴한다.
 * 
 * <b>Parameters</b>
 *    key : 해당 메세지를 출력하기 위한 key값.
 *    targetMsg : key에 포함시킬 메세지
 * 
 * <b>return</b>
 *    content : 해당 메세지를 조합한  후 얻은 결과값.
 *
 * [[사용예]]
 *  => alert( getMessageParam("MSG-0001", "개인정보수정") );
 */
/**
 * @method
 * @name getMessageParam
 * @description desc
 * @param {string} key desc
 * @param {string} targetMsg desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getMessageParam = function(key, targetMsg) {
    var flag = false;
    var content;
    for (i = 0; i < messageKeys.length; i++) {
        if (key == messageKeys[i].key) {
            content = messageKeys[i].content;
            flag = true;
            break;
        }
    }
    if (content == undefined) content = "MessageCode: " + key;
    if (flag == false) content = "MessageCode: " + key;
    var count = content.indexOf("^");
    if (count > -1) {
        content = content.substring(0, count) + targetMsg + content.substring(count + 1);
    }
    return content;
};


