SCREN_PROCS_TP_CD_02 = '02'; // 입력  
SCREN_PROCS_TP_CD_03 = '03'; // 수정  
SCREN_PROCS_TP_CD_04 = '04'; // 삭제  
SCREN_PROCS_TP_CD_05 = '05'; // 인쇄  
SCREN_PROCS_TP_CD_06 = '06'; // 화면출력  
SCREN_PROCS_TP_CD_07 = '07'; // 엑셀저장  
SCREN_PROCS_TP_CD_08 = '08'; // PC저장  


xmlHttp4LogSave; //XMLHttpRequest객체	
alert4LogSave = false; //로그를찍을지여부

//XMLHttpRequest객체	생성
/**
 * @method
 * @name createXMLObj4LogSave
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.createXMLObj4LogSave = function() {
    if (window.ActiveXObject) {
        scwin.xmlHttp4LogSave = new ActiveXObject("Microsoft.XMLHTTP");
    } else if (window.XMLHttpRequest) {
        scwin.xmlHttp4LogSave = new XMLHttpRequest();
    }
};



//log저장을 위한 실제 URL 호출
/**
 * @method
 * @name startLogSave
 * @description desc
 * @param {string} ver1 desc
 * @param {string} ver2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.startLogSave = function(ver1, ver2) {
    var url = "/common/logSaveAct.jsp?SCREN_ID=" + ver1 + "&SCREN_PROCES_TP_CD=" + ver2;
    xmlHttp4LogSave.onreadystatechange = chkStats4LogSave;
    xmlHttp4LogSave.open("GET", url, true);
    xmlHttp4LogSave.send(null);
};
/**
 * @method
 * @name chkStats4LogSave
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkStats4LogSave = function() {
    if (xmlHttp4LogSave.readyState == 4) {
        if (xmlHttp4LogSave.status == 200) {
            scwin.viewParameter4logSave();
        }
    }
};
/**
 * @method
 * @name viewParameter4logSave
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.viewParameter4logSave = function() {
    var xmlDoc = xmlHttp4LogSave.responseXML;
    var node = xmlDoc.getElementsByTagName("result");
    if (scwin.alert4LogSave) alert(node[0].childNodes[0].nodeValue);
};
/**
 * @method
 * @name doLogSave
 * @description desc
 * @param {string} ver1 desc
 * @param {string} ver2 desc
 * @param {string} ver3 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.doLogSave = function(ver1, ver2, ver3) {
    scwin.createXMLObj4LogSave();
    if (ver3) scwin.alert4LogSave = true;
    scwin.startLogSave(ver1, ver2);
};


/*
2008.01.17 김성일
String의 특정 문자열(문자)를 특정문자열(문자)로 바꿈.
*/
/**
 * @method
 * @name replaceAll
 * @description desc
 * @param {string} src_str desc
 * @param {string} src_char desc
 * @param {string} tar_char desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.replaceAll = function(src_str, src_char, tar_char) {
    var reg = new RegExp(src_char, "ig");
    return src_str.replace(reg, tar_char);
};




