/*
	2008.01.17 김성일
	id로 넘겨받은 obj에 담긴 에러 메세지를 alert 시킴.
*/
/**
 * @method
 * @name alert_error
 * @description desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.alert_error = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
        }
    }
};





/*
 * from, to 날짜에 기간구분선택에 따른 날짜 셋팅하기   
 *  - 기간구분 : pTp
 *  - from 객체 이름 : pObjFrom
 *  - to 객체 이름 : pObjTo
 */
/**
 * @method
 * @name fn_setFromToDate
 * @description desc
 * @param {string} pTp desc
 * @param {string} pObjFrom desc
 * @param {string} pObjTo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setFromToDate = function(pTp, pObjFrom, pObjTo) {
    //1주일^1,1개월^2,3개월^3,6개월^4,1년^5,2년^6
    var vFrom = "";
    var vTo = scwin.getObjectValue(pObjTo);
    if (vTo == '') {
        // 값이 없으면 현재일 기준으로 계산
        vTo = $c.ut.cGetToday("yyyymmdd");
    }
    if (pTp == 1) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 7); // 일주일전		

    } else if (pTp == 2) {
        // 1개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 1);
    } else if (pTp == 3) {
        // 3개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 3);
    } else if (pTp == 4) {
        // 6개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 6);
    } else if (pTp == 5) {
        // 1년전
        vFrom = $c.ut.cGetMinusYear(vTo, 1);
    } else if (pTp == 6) {
        // 2년전
        vFrom = $c.ut.cGetMinusYear(vTo, 2);
    }
    scwin.setObjectValue(pObjFrom, vFrom);
    scwin.setObjectValue(pObjTo, vTo);
};



/*
	2008.01.17 김성일
	id로 넘겨받은 obj의 type과 naming rule에 따라 IF을 각각 호출하여 값을 넣는다.
*/
/**
 * @method
 * @name setObjectValue
 * @description desc
 * @param {string} obj desc
 * @param {string} value desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setObjectValue = function(obj, value) {
    // type으로 알수 있는 것은 text랑 checkbox 밖에 없음. 이건 html ctrl을 그대로 사용한 것으로 보임.
    if (obj.type == "text") {
        obj.setValue(value.getValue());
    } else if (obj.type == "checkbox") {
        obj.setValue((value == "Y") ? true : false);
    }
    // 나머진 Naming 으로 판단함.	
    else if (obj.id.indexOf("rdo") > -1) {
        // radio = CodeValue
        obj.setValue(value.getValue());
    } else if (obj.id.indexOf("edt") > -1) {
        // emedit = text
        obj.setValue(value.getValue());
    } else if (obj.id.indexOf("cmb") > -1) {
        // combo = cmb_Tab1_Dep.ValueOfIndex("VALUE", cmb_Tab1_Dep.Index);
        obj.setSelectedIndex(obj.IndexOfColumn("VALUE", value));
    } else if (obj.id.indexOf("txa") > -1) {
        // textarea = text
        obj.setValue(value.getValue());
    }
    return ("");
};


/*
	2008.04.16 김성일 추가.
	특정 패널에 메세지를 표시함.
	예 : 시장조치일정 : 63 개 (미확정 40, 확정 23)
